architecture behav of mult is
begin
  process(a, b) is
    variable ac : unsigned(2*N-1 downto 0);
    constant z_extend :
      unsigned(2*N-1 downto N) := (others => '0');
  begin
    ac := (others => '0');
    for i in N-1 downto 0 loop
      ac := ac(ac'left-1 downto 0) & '0';
      if b(i) = '1' then
        ac := ac + (z_extend & unsigned(a));
      end if;
