architecture behav of receiver is
  type state_type is (ruhe, empfang);
  signal state : state_type;
  signal ser_in_d, ser_in_dd : std_logic;
  signal teiler : integer range 0 to BIT_TAKTE - 1;
  signal bitnr  : integer range 0 to 9;
  signal data   : std_logic_vector(9 downto 0);
begin
  process(clk, res_n) is
  begin
    if res_n = '0' then
      state <= ruhe;
      ser_in_d <= '0';
      ser_in_dd <= '0';
      teiler <= 0;
      bitnr <= 0;
      data <= (others => '0');
      par_out_ena <= '0';
    else
      if clk'event and clk = '1' then
        ser_in_d  <= ser_in;
        ser_in_dd <= ser_in_d;
        par_out_ena <= '0';
        case state is
          when ruhe =>
            if ser_in_dd = '1' then
              state  <= empfang;
              teiler <= BIT_TAKTE / 2;
              bitnr  <= 0;
            end if;
          when empfang =>
            if teiler = BIT_TAKTE - 1 then
              teiler <= 0;
              data <= ser_in_dd & data(9 downto 1);
              if bitnr = 9 then
                state <= ruhe;
                par_out_ena <= '1';
              else
                bitnr <= bitnr + 1;
              end if;
            else
              teiler <= teiler + 1;
            end if;
        end case;
      end if;
    end if;
  end process;
  par_out <= data(8 downto 1);
end architecture behav;

