architecture behav of fsm is
  type state_type is (operand, operator, fehler);
  signal current_state, next_state : state_type;
begin
  transition_function: process(current_state, x, tos) is
  begin
    next_state <= current_state;
    y <= '*'; push <= epsilon; pop <= false; clr <= false;
    if x = '!' then
      clr <= true;
      next_state <= operand;
      if current_state = operator and tos = eos then
        y <= '1';
      else
        y <= '0';
      end if;
    else
      case current_state is
        when operand =>
          case x is
            when 'x'    => next_state <= operator;
            when '('    => push <= '(';
            when '['    => push <= '[';
            when others => next_state <= fehler;
          end case;
        when operator =>
          case x is
            when '-' =>
              if tos = '[' then
                next_state <= fehler;
              else
                next_state <= operand;
              end if;
            when ')' =>
              if tos = '(' then pop <= true;
              else next_state <= fehler; end if;
            when ']' =>
              if tos = '[' then pop <= true;
              else next_state <= fehler; end if;
            when others =>
              next_state <= fehler;
          end case;
        when fehler =>
          null;
      end case;
    end if;
  end process transition_function;

  state: process(clk, res_n) is
  begin
    if res_n = '0' then
      current_state <= operand;
    else
      if clk'event and clk = '1' then
        current_state <= next_state;
      end if;
    end if;
  end process state;
end architecture behav;

